    const deWords = ['und', 'der', 'die', 'das', 'ist', 'nicht', 'wird', 'für', 'auf', 'mit', 'von', 'werden', 'gemäß', 'vereinbarung', 'vertrag'];
    const deCount = deWords.filter(w => new RegExp(`\\b${w}\\b`).test(sample)).length;
