router.get('/:id/analysis/stream', auth_1.authenticateToken, async (req, res) => {
    const userId = req.user.userId;
    const documentId = req.params.id;
    const document = await prisma.document.findFirst({
        where: { id: documentId, userId },
    });
    if (!document) {
        return res.status(404).json({ error: 'Document not found' });
    }
    if (document.status === 'completed') {
        return res.json({
            status: 'completed',
            message: 'Document already analyzed',
        });
    }
    if (document.status === 'processing') {
        return res.json({
            status: 'processing',
            message: 'Document analysis already in progress. Please wait for completion.',
        });
    }
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');
    res.setHeader('X-Accel-Buffering', 'no');
    res.flushHeaders();
    const sendEvent = (event, data) => {
        res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
    };
    try {
        for await (const event of streamDocumentAnalysis(documentId, document.filepath, userId, { ipAddress: req.ip, userAgent: req.headers['user-agent'] })) {
            sendEvent(event.type, event.data);
        }
        sendEvent('done', { complete: true });
    }
    catch (error) {
        sendEvent('error', { message: error.message });
    }
    finally {
        res.end();
    }
});
